:root {
  --amber-dark: #b45309;
  --amber-mid: #d97706;
  --amber-light: #fef3c7;
  --amber-pale: #fffbeb;
  --green: #15803d;
  --green-light: #dcfce7;
  --warn: #92400e;
  --warn-light: #fde68a;
  --text-primary: #1c1917;
  --text-muted: #78716c;
  --border: #e7d5a8;
  --white: #ffffff;
  --stat-bg: #fdf6e3;
}

.hive-card {
  width: 480px;
  background-color: var(--amber-pale);
  border: 2px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
  font-size: 14px;
  color: var(--text-primary);
}

.hive-header {
  background-color: var(--amber-mid);
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.hive-title-group {
  display: flex;
  align-items: center;
  gap: 10px;
}

.hive-icon {
  font-size: 28px;
  line-height: 1;
}

.hive-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--white);
  margin: 0;
  line-height: 1.2;
}

.hive-date {
  font-size: 12px;
  color: var(--amber-light);
  margin: 2px 0 0;
}

.hive-status {
  background-color: var(--green-light);
  color: var(--green);
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
}

.hive-body {
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hive-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.stat-block {
  background-color: var(--stat-bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stat-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--amber-dark);
  line-height: 1;
}

.stat-label {
  font-size: 11px;
  color: var(--text-muted);
  text-align: center;
}

.hive-checks {
  display: flex;
  gap: 12px;
}

.checklist {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 148px;
}

.check-item {
  font-size: 13px;
  padding: 5px 10px;
  border-radius: 6px;
  font-weight: 500;
}

.check-item.done {
  background-color: var(--green-light);
  color: var(--green);
}

.check-item.warn {
  background-color: var(--warn-light);
  color: var(--warn);
}

.hive-notes {
  flex: 1;
  background-color: var(--white);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 12px;
}

.notes-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--amber-dark);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin: 0 0 4px;
}

.notes-text {
  font-size: 13px;
  color: var(--text-primary);
  line-height: 1.5;
  margin: 0;
}

.hive-footer {
  background-color: var(--amber-light);
  border-top: 1px solid var(--border);
  padding: 9px 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.inspector-tag {
  font-size: 13px;
  font-weight: 600;
  color: var(--amber-dark);
}

.next-date {
  font-size: 12px;
  color: var(--text-muted);
  font-weight: 500;
}
